"""Canonical Tasks view, shared focus and mobile Compact Preview in isolated data."""
import json


def run_task_view_checks(*,cdp,e,check,wait_for,add,shot):
    q=json.dumps
    check(e('document.getElementById("tasks-section").hidden'),'no empty Tasks block before first checklist')
    check(e('constellationWorkspace.collapsed&&document.getElementById("constellation-list").hidden'),'empty Constellations stays compact and collapsed by default')
    travel=add('Travel');japan=add('Japan',travel)
    home=add('Home');kitchen=add('Kitchen',home)
    learning=add('Learning');course=add('Course',learning)

    def create(name,parent,names):
        e(f'createChildEntry({q(parent)},true);fields[0].value={q(name)};document.getElementById("task-list-tasks").value={q(chr(10).join(names))};form.requestSubmit();applicationCommandTail')
        wait_for('!dialog.open&&!formSaveBusy');return e('selectedNode.dataset.entryId')
    trip=create('Before the trip',japan,['Flight','Hotel','Car','eSIM'])
    renovation=create('Renovation tasks',kitchen,['Cabinets','Paint','Lighting'])
    assignments=create('Assignments',course,['Read','Research','Write','Review','Submit'])
    flight,hotel,car,esim=e(f'galaxyModel.childrenOf(entries,{q(trip)}).map(x=>x.id)')
    trip_tasks=[flight,hotel,car,esim]
    def listrow(id):return f'#tasks-view [data-task-list-id="{id}"]'
    def taskrow(id):return f'#tasks-view [data-task-id="{id}"]'
    def marker(id):return taskrow(id)+' .task-view-check'
    def universe(id):return f'.hierarchy-row[data-entry-id="{id}"] .tree-task-toggle'
    def click(selector,touch=False):
        e(f'document.querySelector({q(selector)}).scrollIntoView({{block:"nearest"}});new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
        p=e(f'(()=>{{const r=document.querySelector({q(selector)}).getBoundingClientRect();return {{x:r.x+r.width/2,y:r.y+r.height/2}}}})()')
        if touch:
            cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[p]);cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[])
        else:
            cdp.call('Input.dispatchMouseEvent',type='mousePressed',button='left',clickCount=1,**p);cdp.call('Input.dispatchMouseEvent',type='mouseReleased',button='left',clickCount=1,**p)
        e('applicationCommandTail');wait_for('camera.frame===null')
    def select(id,opened=True):
        e(f'selectEntry(entries.get({q(id)}),nodes.get({q(id)}),{{reframe:false,openInspector:{str(opened).lower()}}});camera.stopAnimation();physics.pause()')
    def sync(id,value):
        return e(f'entries.get({q(id)}).completed==={str(value).lower()}&&document.querySelector({q(marker(id))}).getAttribute("aria-checked")==={q(str(value).lower())}&&document.querySelector({q(universe(id))}).getAttribute("aria-checked")==={q(str(value).lower())}&&document.getElementById("content-task-done").checked==={str(value).lower()}&&document.getElementById("mobile-task-done").checked==={str(value).lower()}')
    check(e(f'[...document.querySelectorAll("#tasks-active > li")].map(x=>x.dataset.taskListId).join("|")==={q("|".join([trip,renovation,assignments]))}'),'Task Lists from unrelated Galaxies appear together in stable model order')
    check(e('document.querySelectorAll("#tasks-active > li").length===3&&!document.getElementById("tasks-section").hidden'),'secondary view contains lists rather than regular CBs')
    check(e('!document.querySelector("#tasks-view [role=tree]")'),'Tasks is a checklist view, not a duplicate hierarchy tree')
    check(e(f'document.querySelector({q(listrow(trip)+" .tasks-children")}).hidden'),'individual Task Lists start collapsed')
    e('window.taskPulseVisibility=[];window.taskFocusPulses=[];window.viewsPulse=motion.taskComplete.bind(motion);motion.taskComplete=(node,delay)=>{taskFocusPulses.push(node?.dataset.entryId);taskPulseVisibility.push({id:node?.dataset.entryId,visible:node?.dataset.culled!=="true",rest:camera.frame===null});return viewsPulse(node,delay)};physics.pause();camera.stopAnimation()')
    select(japan)
    e('hierarchySidebar.setCollapsed(false)')
    expanded=e('[...hierarchySidebar.expanded]')
    click(listrow(trip)+' .tasks-list-disclosure')
    check(e(f'!document.querySelector({q(listrow(trip)+" .tasks-children")}).hidden&&document.querySelectorAll({q(listrow(trip)+" .tasks-task-row")}).length===4'),'secondary disclosure exposes every direct task')
    check(e(f'JSON.stringify([...hierarchySidebar.expanded])===JSON.stringify({q(expanded)})'),'secondary disclosure does not change Universe tree disclosure')
    before=e('entries.size')
    click(marker(flight))
    check(e(f'selectedNode.dataset.entryId==={q(flight)}&&entries.size==={before}'),'global checkbox focuses the real canonical task without copies')
    check(sync(flight,True),'global completion synchronizes all four controls')
    check(e(f'taskStates.get({q(trip)}).ratio===.25&&nodes.get({q(trip)}).style.getPropertyValue("--task-ratio")==="0.25"&&nodes.get({q(flight)}).dataset.taskComplete==="true"'),'completion updates direct progress, ring ratio and alive artwork')
    check(e(f'taskFocusPulses.includes({q(flight)})&&!hierarchySidebar.collapsed&&tasksView.expanded.has({q(trip)})'),'visible completion pulse plays after focus and sidebar/disclosure remains open')
    check(e(f'taskPulseVisibility.some(x=>x.id==={q(flight)}&&x.visible&&x.rest)'), 'completion pulse waits until camera arrival on a visible CB')
    check(e(f'document.querySelector({q(listrow(trip)+" .tasks-summary")}).textContent==="1/4"&&document.querySelectorAll({q(listrow(trip)+" .tasks-task-row")}).length===4'),'completed and incomplete tasks remain visible together with restrained summary')
    check(e(f'(()=>{{const b=physics.bounds,p=camera.worldToScreen(entries.get({q(flight)}).x,entries.get({q(flight)}).y);return p.x>=b.left&&p.x<=b.right&&p.y>=b.top&&p.y<=b.bottom&&camera.view.scale<=3}})()'),'completion uses sensible existing framing inside available canvas')
    select(japan)
    camera_before=e('({...camera.view})');pulse_count=e('taskFocusPulses.length')
    click(marker(flight))
    check(e(f'selectedNode.dataset.entryId==={q(japan)}&&JSON.stringify(camera.view)===JSON.stringify({q(camera_before)})&&taskFocusPulses.length==={pulse_count}'),'unchecking from secondary view does not navigate or celebrate')
    e(f'document.querySelector({q(marker(flight))}).focus()')
    cdp.call('Input.dispatchKeyEvent',type='keyDown',key=' ',code='Space',windowsVirtualKeyCode=32)
    cdp.call('Input.dispatchKeyEvent',type='keyUp',key=' ',code='Space',windowsVirtualKeyCode=32)
    e('applicationCommandTail');wait_for('camera.frame===null')
    check(sync(flight,True), 'secondary checkbox is keyboard operable and uses shared completion')
    click(marker(flight))
    click(universe(flight))
    check(sync(flight,True) and e(f'selectedNode.dataset.entryId==={q(flight)}'),'Universe sidebar completion uses same focus and synchronization')
    click('#content-task-done')
    check(sync(flight,False),'Contents uncheck updates all four controls')
    click('#content-task-done')
    check(sync(flight,True) and e(f'selectedNode.dataset.entryId==={q(flight)}'),'Contents completion focuses its task')
    click(marker(hotel))
    other_tasks=e(f'[galaxyModel.childrenOf(entries,{q(renovation)})[0].id,...galaxyModel.childrenOf(entries,{q(assignments)}).slice(0,2).map(x=>x.id)]')
    for id in other_tasks:
        e(f'changeTask({q(id)},"completed",true)');wait_for('camera.frame===null')
    e(f'focusEntry({q(trip)});physics.pause()');wait_for('camera.frame===null')
    e('document.getElementById("sidebar-secondary-views").scrollTop=0')
    check(e(f'taskStates.get({q(trip)}).done===2&&taskStates.get({q(renovation)}).done===1&&taskStates.get({q(assignments)}).done===2'), 'real review scene has independent 2/4, 1/3 and 2/5 checklist progress')
    shot('task-views-real-review-desktop')
    for id in [car,esim]:click(marker(id))
    check(e(f'taskStates.get({q(trip)}).complete&&document.querySelector({q(listrow(trip))}).parentElement.id==="tasks-completed"'),'finished Task List moves into Completed grouping')
    check(e(f'document.getElementById("tasks-completed").hidden&&!document.querySelector({q(listrow(trip)+" .tasks-children")}).hidden'),'completion respects collapsed Completed preference and retains checklist disclosure')
    check(e(f'taskFocusPulses.includes({q(trip)})'),'final completion retains parent pulse')
    click('#tasks-completed-toggle')
    click(marker(car))
    check(e(f'document.querySelector({q(listrow(trip))}).parentElement.id==="tasks-active"'),'unchecking returns completed list to active group')
    click(marker(car));click('#tasks-completed-toggle')
    check(e('document.getElementById("tasks-completed").hidden'),'Completed grouping can be collapsed independently')
    # Reload tests completed defaults, rather than persisting a second task dataset.
    cdp.call('Page.reload',ignoreCache=True)
    wait_for('document.readyState==="complete"&&typeof tasksView!=="undefined"&&entries.size>0')
    check(e(f'document.querySelector({q(listrow(trip))}).parentElement.id==="tasks-completed"&&document.getElementById("tasks-completed").hidden'),'reload derives completed lists and starts Completed collapsed')
    check(e('!localStorage.getItem("galaxy:navigation-ui")||!JSON.parse(localStorage.getItem("galaxy:navigation-ui")).taskRows'),'no duplicated task data is persisted for secondary view')
    e('hierarchySidebar.setCollapsed(false)');click('#tasks-completed-toggle');click(listrow(trip)+' .tasks-list-disclosure');click(marker(car))
    select(car)
    # Dynamic updates use the existing mutation and repository paths.
    e(f'renameEntry({q(car)},"Rental car");applicationCommandTail')
    check(e(f'document.querySelector({q(taskrow(car)+" .tasks-task-name")}).textContent==="Rental car"'),'task rename updates secondary view')
    e(f'renameEntry({q(trip)},"Trip preparation");applicationCommandTail')
    check(e(f'document.querySelector({q(listrow(trip)+" .tasks-list-name")}).textContent==="Trip preparation"'),'Task List rename updates secondary view')
    extra=add('Extra task',trip)
    check(e(f'document.querySelectorAll({q(listrow(trip)+" .tasks-task-row")}).length===5'),'adding a task updates checklist and denominator')
    e(f'moveSidebarEntries({{ids:[{q(extra)}],activeId:{q(extra)}}},{q(renovation)})')
    check(e(f'!document.querySelector({q(listrow(trip)+" [data-task-id="+q(extra)+"]")})&&!!document.querySelector({q(listrow(renovation)+" [data-task-id="+q(extra)+"]")})'),'moving between lists updates both secondary checklists')
    e(f'moveSidebarEntries({{ids:[{q(extra)}],activeId:{q(extra)}}},{q(kitchen)})')
    check(e(f'!document.querySelector({q(taskrow(extra))})'),'moving task out removes its secondary task entry')
    temporary=add('Delete this task',trip)
    e(f'requestEntryDelete({q(temporary)});document.getElementById("delete-entry-form").requestSubmit();applicationCommandTail');wait_for('!deletionBusy')
    check(e(f'!document.querySelector({q(taskrow(temporary))})&&taskStates.get({q(trip)}).total===4'), 'deleting a task updates secondary view and summary')
    e(f'moveSidebarEntries({{ids:[{q(trip)}],activeId:{q(trip)}}},{q(home)})')
    check(e(f'document.querySelector({q(listrow(trip)+" .tasks-list-name")}).title.includes("Home")'),'moving Task List retains view and updates contextual tooltip')
    e(f'openDuplicateStructure({q(trip)});structureName.value="Next trip";structureForm.requestSubmit();applicationCommandTail');wait_for('!structureBusy')
    duplicate=e('selectedNode.dataset.entryId')
    check(e(f'!!document.querySelector({q(listrow(duplicate))})&&taskStates.get({q(duplicate)}).done===0'),'duplicate Task List appears with reset completion')
    e(f'requestEntryDelete({q(duplicate)});document.getElementById("delete-entry-form").requestSubmit();applicationCommandTail');wait_for('!deletionBusy')
    check(e(f'!document.querySelector({q(listrow(duplicate))})'),'deleted Task List is removed from secondary view')
    # Constellations remain separate/manual; default collapse respects saved UI preference.
    check(e('constellations.size===0'),'Tasks view never creates automatic Constellations')
    e('constellationWorkspace.openName();document.getElementById("constellation-name").value="Trip favorites";document.getElementById("constellation-name-form").requestSubmit();applicationCommandTail')
    wait_for('!constellationWorkspace.savingName')
    collection=e('[...constellations.keys()][0]')
    check(e('constellations.size===1&&constellationWorkspace.collapsed'),'Constellations creation stays available without permanent expansion')
    e(f'constellationWorkspace.setMember({q(collection)},{q(car)},true)')
    click('#constellations-toggle')
    check(e('!document.getElementById("constellation-list").hidden'),'Constellations can still expand normally')
    click(f'#constellation-list [data-constellation-id="{collection}"] .constellation-open')
    check(e(f'activeConstellationId==={q(collection)}&&constellations.get({q(collection)}).memberEntryIds.includes({q(car)})'),'manual Constellation navigation and membership still work')
    e('exitConstellation();physics.pause()')
    shot('task-views-desktop')
    # All mobile controls use native touch, with normal selected CBs unchanged.
    for width,height in [(360,800),(390,844),(430,932)]:
        cdp.call('Emulation.setDeviceMetricsOverride',width=width,height=height,deviceScaleFactor=1,mobile=True)
        cdp.call('Emulation.setTouchEmulationEnabled',enabled=True,maxTouchPoints=5)
        wait_for('hierarchySidebar.narrow');e('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
        e('closeInspector();hierarchySidebar.setCollapsed(true)');select(japan,False)
        check(e('document.getElementById("mobile-task-quick").hidden'),'regular Compact Preview unchanged: '+str(width))
        select(trip,False)
        check(e('document.getElementById("mobile-task-control").hidden&&!document.getElementById("mobile-task-progress").hidden'),'Task List Compact Preview has progress, no Done: '+str(width))
        select(car,False)
        check(e('!document.getElementById("mobile-task-control").hidden&&panel.hidden'),'task Done is immediately available in Compact Preview: '+str(width))
        check(e('(()=>{const r=document.getElementById("mobile-task-control").getBoundingClientRect(),card=document.getElementById("mobile-body-actions").getBoundingClientRect(),a=document.getElementById("mobile-body-add").getBoundingClientRect(),m=document.getElementById("mobile-body-more").getBoundingClientRect(),n=document.getElementById("mobile-body-name").getBoundingClientRect();return r.height>=44&&r.width>=44&&card.right<=innerWidth&&card.left>=0&&a.right<=m.left&&n.right<=a.left&&card.height<=120})()'),'compact 44px Done target fits with title/+ and More: '+str(width))
        # Normalize to incomplete and focus using the ordinary navigation before taking stable framing.
        if e(f'entries.get({q(car)}).completed'):click('#mobile-task-done',True)
        e(f'focusEntry({q(car)},{{openInspector:false}})');wait_for('camera.frame===null');e('physics.pause()')
        before=e('({...camera.view})')
        click('#mobile-task-done',True)
        check(sync(car,True),'Compact Preview check synchronizes all surfaces: '+str(width))
        check(e(f'JSON.stringify(camera.view)===JSON.stringify({q(before)})&&panel.hidden'),'already-focused Preview completion keeps camera stable and stays compact: '+str(width))
        click('#mobile-body-name',True)
        check(e('!!document.querySelector("#mobile-body-actions .title-rename-form:not([hidden])")&&document.getElementById("mobile-task-done").checked'),'task title rename remains available beside Compact Done: '+str(width))
        click('#mobile-body-actions .title-rename-form button[type=button]',True)
        check(e(f'entries.get({q(car)}).name==="Rental car"&&document.getElementById("mobile-task-done").checked&&panel.hidden'),'task title Cancel preserves name and Done state: '+str(width))
        shot('task-compact-done-'+str(width))
        click('#mobile-body-add',True)
        check(e('[...addMenu.querySelectorAll("button:not([hidden])")].map(b=>b.textContent).join("|")==="Take Photo|Photo Gallery"'),'task Compact + retains capture menu: '+str(width))
        e('closeContentMenus()');click('#mobile-body-more',True)
        check(e(f'!contextMenu.hidden&&contextEntryId==={q(car)}'),'Compact More retains canonical task target: '+str(width));e('closeContextMenu()')
        if width==390:
            p=e('(()=>{const r=document.getElementById("mobile-body-contents").getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2}})()')
            cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[p])
            for dy in [20,45,80]:cdp.call('Input.dispatchTouchEvent',type='touchMove',touchPoints=[dict(x=p['x'],y=p['y']-dy)])
            cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[])
            wait_for('mobileContents.state==="browse"')
        else:click('#mobile-body-contents',True)
        check(e('mobileContents.state==="browse"&&document.getElementById("content-task-done").checked'),'Preview to Contents opens with synchronized Done: '+str(width))
        click('#content-task-done',True)
        check(sync(car,False),'Contents uncheck synchronizes Preview and both sidebars: '+str(width))
        e('closeInspector();hierarchySidebar.setCollapsed(false)')
        click(marker(car),True)
        check(sync(car,True) and e('hierarchySidebar.collapsed'),'mobile secondary completion reveals the focused task: '+str(width))
        e('hierarchySidebar.setCollapsed(false)')
        check(e('(()=>{const r=document.getElementById("sidebar-secondary-views").getBoundingClientRect(),u=hierarchySidebar.tree.getBoundingClientRect();return r.bottom<=innerHeight&&u.height>80})()'),'secondary views leave primary Universe usable: '+str(width))
        shot('task-views-mobile-'+str(width))
        wait_for('camera.frame===null')
        before=e('({...camera.view})');click(marker(car),True)
        check(sync(car,False) and e(f'JSON.stringify(camera.view)===JSON.stringify({q(before)})'),'mobile uncheck never forces camera travel: '+str(width))
        if width==430:
            e(f'document.querySelector({q(marker(flight))}).scrollIntoView({{block:"center"}})')
            before_scroll=e('document.getElementById("sidebar-secondary-views").scrollTop')
            p=e(f'(()=>{{const r=document.querySelector({q(marker(flight))}).getBoundingClientRect();return {{x:r.x+r.width/2,y:r.y+r.height/2}}}})()')
            cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[p])
            for dy in [15,35,65,95,125]:cdp.call('Input.dispatchTouchEvent',type='touchMove',touchPoints=[dict(x=p['x'],y=p['y']-dy)])
            cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[])
            wait_for(f'document.getElementById("sidebar-secondary-views").scrollTop>{before_scroll}')
            check(e(f'entries.get({q(flight)}).completed'),'scrolling a secondary checklist from its checkbox does not toggle it')
            e('new Promise(resolve=>{const view=document.getElementById("sidebar-secondary-views");let previous=view.scrollTop,stable=0;const frame=()=>{const top=view.scrollTop;stable=top===previous?stable+1:0;previous=top;if(stable>=4)resolve();else requestAnimationFrame(frame)};requestAnimationFrame(frame)})')
        click(taskrow(car)+' .tasks-task-name',True)
        check(e(f'selectedNode.dataset.entryId==={q(car)}&&hierarchySidebar.collapsed&&!entries.get({q(car)}).completed'),'task name navigates to actual CB without checking: '+str(width))
    e('camera.setReducedMotion(true);motion.setReducedMotion(true);hierarchySidebar.setCollapsed(false)')
    click(marker(car),True)
    check(sync(car,True) and e('camera.frame===null&&motion.animations.size===0'),'reduced motion still focuses completion with immediate camera and no pulse animation')
    e('hierarchySidebar.setCollapsed(false)')
    check(e('document.getElementById("sidebar-secondary-views").scrollHeight>document.getElementById("sidebar-secondary-views").clientHeight'),'secondary views retain their own scrolling without crowding the Universe')
    click('#tasks-toggle',True)
    check(e('tasksView.section.collapsed&&document.getElementById("tasks-view").hidden'),'Tasks heading collapses independently')
    e('(async()=>{await applicationCommandTail;if(graphNeedsSave)await saveGalaxy();const backup=await cosmifoldBackup.create(universeRepository);await cosmifoldRestore.restore(await cosmifoldRestore.inspect(backup.blob),universeRepository)})()')
    cdp.call('Page.reload',ignoreCache=True)
    wait_for('document.readyState==="complete"&&typeof tasksView!=="undefined"&&entries.size>0')
    check(e(f'entries.get({q(trip)}).taskList&&taskStates.get({q(trip)}).complete&&document.querySelector({q(listrow(trip))}).parentElement.id==="tasks-completed"'),'real Backup/Restore rebuilds secondary view from canonical Task Lists and completion')
    check(e('tasksView.section.collapsed&&tasksView.completedSection.collapsed===persistence.preferences.load().tasksCompletedCollapsed'),'Restore preserves Tasks and Completed disclosure preferences')
    check(e('!constellationWorkspace.collapsed'),'saved explicit Constellations expansion overrides quiet default')
    check(not cdp.errors,'no Tasks view or Compact Preview browser exceptions')
